	@Test
	void remoteModifiersPreserveEndpointInputThroughNestedJoin() {
		Service[] control = new Service[1];
		parse("SELECT * WHERE { SERVICE ?endpoint { ?s <urn:remote> ?remote } }")
				.visit(new AbstractQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(Service service) {
						control[0] = service.clone();
					}
				});
		assertThat(evaluate(strategy(), new QueryRoot(new Join(values("endpoint", VF.createIRI("urn:first")),
				new Join(control[0], values("marker", VF.createIRI("urn:marker"))))), EmptyBindingSet.getInstance()))
						.containsExactly(serviceRow("urn:first"));
		for (String modifier : List.of("LIMIT 1", "OFFSET 1", "DISTINCT", "REDUCED")) {
			String select = modifier.equals("DISTINCT") || modifier.equals("REDUCED")
					? "SELECT " + modifier + " ?s ?remote"
					: "SELECT ?s ?remote";
			String suffix = modifier.equals("DISTINCT") || modifier.equals("REDUCED") ? "" : modifier;
			Service[] services = new Service[1];
			parse("SELECT * WHERE { SERVICE ?endpoint { { " + select
					+ " WHERE { ?s <urn:remote> ?remote OPTIONAL { ?s <urn:optional> ?optional } } " + suffix
					+ " } ?s <urn:other> ?other } }").visit(new AbstractQueryModelVisitor<RuntimeException>() {
						@Override
						public void meet(Service service) {
							services[0] = service.clone();
						}
					});
			QueryRoot original = new QueryRoot(new Join(values("endpoint", VF.createIRI("urn:first"),
					VF.createIRI("urn:second")), new Join(services[0], values("marker", VF.createIRI("urn:marker")))));
			List<BindingSet> expected = List.of(serviceRow("urn:first"), serviceRow("urn:second"));
			assertThat(assertDoesNotThrow(() -> evaluate(strategy(), original.clone(), EmptyBindingSet.getInstance())))
					.as("direct " + modifier)
					.containsExactlyInAnyOrderElementsOf(expected);
			QueryRoot candidate = original.clone();
			new QueryJoinOptimizer(new EvaluationStatistics() {
				@Override
				public double getCardinality(TupleExpr expression) {
					return expression instanceof Service ? 0.1
							: expression.getBindingNames().contains("marker") ? 10000 : 2;
				}
			}, new EmptyTripleSource()).optimize(candidate, null, EmptyBindingSet.getInstance());
			assertThat(evaluate(strategy(), candidate, EmptyBindingSet.getInstance()))
					.as(modifier)
					.containsExactlyInAnyOrderElementsOf(expected);
		}
	}

	@Test
	void oneShotValuesSurviveStandaloneOptimizersAndDefaultPipeline() {
		List<BindingSet> boundRows = List.of(new ListBindingSet(List.of("x"), VF.createLiteral(1)),
				new ListBindingSet(List.of("x"), VF.createLiteral(2)),
				new ListBindingSet(List.of("x"), VF.createLiteral(3)));
		List<BindingSet> undefRows = List.of(new MapBindingSet(), boundRows.get(0), boundRows.get(1));
		List<BindingSet> nullSlotRows = List.of(new ListBindingSet(List.of("x"), (Value) null), boundRows.get(0),
				boundRows.get(1));
		List<BindingSet> extraRows = List.of(new ListBindingSet(List.of("x", "extra"), VF.createLiteral(1), null),
				boundRows.get(1),
				new ListBindingSet(List.of("x", "extra"), VF.createLiteral(3), VF.createIRI("urn:extra")));
		for (List<BindingSet> rows : List.of(boundRows, undefRows, nullSlotRows, extraRows, List.<BindingSet>of())) {
			List<BindingSet> expected = rows.stream().filter(row -> row.hasBinding("x")).map(row -> {
				MapBindingSet mapping = new MapBindingSet();
				row.forEach(mapping::addBinding);
				return (BindingSet) mapping;
			}).toList();
			for (String optimizer : List.of("constant", "inliner", "pipeline")) {
				BindingSetAssignment assignment = new BindingSetAssignment();
				assignment.setDeclaredBindingNames(Set.of("x"));
				assignment.setBindingSets(new OneShotRows(rows));
				QueryRoot root = new QueryRoot(new Filter(assignment, new Bound(Var.of("x"))));
				DefaultEvaluationStrategy strategy = strategy();
				if (optimizer.equals("constant")) {
					new ConstantOptimizer(strategy).optimize(root, null, EmptyBindingSet.getInstance());
				} else if (optimizer.equals("inliner")) {
					new BindingSetAssignmentInlinerOptimizer().optimize(root, null, EmptyBindingSet.getInstance());
				} else {
					strategy.optimize(root, new EvaluationStatistics(), EmptyBindingSet.getInstance());
				}
				assertThat(evaluate(strategy, root, EmptyBindingSet.getInstance())).as("%s rows=%s", optimizer, rows)
						.containsExactlyElementsOf(expected);
			}
		}
	}

