	@Test
	void volatileSourcesAreEvaluatedOnlyAtRuntimeForEveryInvocation() {
		AtomicInteger calls = new AtomicInteger();
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of("x"));
		assignment.setBindingSets(() -> List.<BindingSet>of(new ListBindingSet(List.of("x"),
				VF.createLiteral(calls.incrementAndGet()))).iterator());
		QueryEvaluationStep compiled = strategy().precompile(new QueryRoot(assignment));
		assertThat(calls).hasValue(0);
		for (int invocation = 1; invocation <= 2; invocation++) {
			try (CloseableIteration<BindingSet> rows = compiled.evaluate(EmptyBindingSet.getInstance())) {
				assertThat(rows.next().getValue("x")).isEqualTo(VF.createLiteral(invocation));
				assertThat(rows.hasNext()).isFalse();
			}
		}
		assertThat(calls).hasValue(2);
	}

	@Test
	void foldingPreservesLocallyAssignedProjectionTargets() {
		MapBindingSet input = new MapBindingSet();
		input.addBinding("x", VF.createLiteral(2));
		for (String query : List.of(
				"SELECT ?x WHERE { BIND(1 AS ?x) FILTER(?x = 1) }",
				"SELECT ?x WHERE { BIND(IF(true, 1, ?x) AS ?x) FILTER(?x = 1) }",
				"SELECT (?x AS ?result) WHERE { BIND(1 AS ?x) FILTER(?x = 1) }",
				"SELECT ?x WHERE { { SELECT ?x WHERE { BIND(1 AS ?x) FILTER(?x = 1) } } }",
				"SELECT ?x ?y WHERE { BIND(1 AS ?x) BIND(?x + 1 AS ?y) FILTER(?x = 1 && ?y = 2) }")) {
			TupleExpr original = parse(query);
			List<BindingSet> expected = evaluate(strategy(), original.clone(), input);
			assertThat(expected).singleElement()
					.satisfies(row -> assertThat(row.getValue(
							query.contains("?result") ? "result" : "x")).isEqualTo(VF.createLiteral("1", XSD.INTEGER)));
			for (boolean pipeline : List.of(false, true)) {
				TupleExpr candidate = original.clone();
				DefaultEvaluationStrategy strategy = strategy();
				if (pipeline) {
					strategy.optimize(candidate, new EvaluationStatistics(), input);
				} else {
					new ConstantOptimizer(strategy).optimize(candidate, null, input);
				}
				assertThat(evaluate(strategy, candidate, input)).as(query + " pipeline=" + pipeline)
						.containsExactlyElementsOf(expected);
			}
		}
	}

